// @vitest-environment happy-dom
import { describe, it, expect } from "vitest";
import { htmlToMarkdown, isJiraXml, jiraXmlToTable } from "./jira-xml";
import { csvToBundle, guessTargets } from "./csv";
import { parseBundle } from "./bundle";

const esc = (html: string) => html.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

// Shaped like Jira's "Export XML", with made-up issues
const XML = `<?xml version="1.0" encoding="utf-8"?>
<!-- RSS generated by JIRA -->
<rss version="0.92"><channel><title>Jira</title>
<item>
  <title>[ORB-12] Export invoices</title>
  <description>${esc("<h2>Context</h2> <p>The <tt>InvoiceRepository</tt> &amp; its <b>six</b> methods.</p> <ul><li>one</li><li>two <a href=\"https://example.com\">link</a></li></ul>")}</description>
  <key id="10012">ORB-12</key>
  <summary>Export invoices</summary>
  <type id="1">Story</type>
  <parent id="10010">ORB-10</parent>
  <priority id="3">Normal</priority>
  <status id="5">Done</status>
  <assignee accountid="712020:aaa">Maya Kowalska</assignee>
  <reporter accountid="712020:bbb">Jan Nowak</reporter>
  <labels><label>billing</label><label>q3</label></labels>
  <created>Tue, 18 Aug 2026 10:16:16 +0200</created>
  <resolved>Fri, 21 Aug 2026 14:58:19 +0200</resolved>
  <due>Mon, 31 Aug 2026 00:00:00 +0200</due>
  <comments>
    <comment id="501" author="712020:bbb" created="Wed, 19 Aug 2026 09:00:00 +0200">${esc("<p>Looks good; ship it</p>")}</comment>
    <comment id="502" author="712020:zzz" created="Thu, 20 Aug 2026 11:30:00 +0000">${esc("<p>Second</p>")}</comment>
  </comments>
</item>
<item>
  <title>[ORB-13] Sign in</title>
  <description></description>
  <key id="10013">ORB-13</key>
  <summary>Sign in</summary>
  <type id="2">Bug</type>
  <priority id="1">Highest</priority>
  <status id="1">To Do</status>
  <assignee accountid="-1">Unassigned</assignee>
  <reporter accountid="712020:bbb">Jan Nowak</reporter>
  <labels> </labels>
  <created>Sat, 22 Aug 2026 08:00:00 +0000</created>
  <resolved/>
  <due/>
</item>
</channel></rss>`;

describe("a Jira XML export", () => {
  it("is recognised, and laid out as Jira's CSV export would be", () => {
    expect(isJiraXml(XML)).toBe(true);
    expect(isJiraXml("<rss><channel></channel></rss>")).toBe(false);
    const table = jiraXmlToTable(XML, new DOMParser())!;
    expect(table.headers).toEqual([
      "Issue key", "Summary", "Issue Type", "Status", "Priority", "Assignee", "Created", "Resolved", "Due date", "Parent", "Description",
      "Labels", "Labels",
    ]);
    expect(table.rows[0]).toEqual([
      "ORB-12", "Export invoices", "Story", "Done", "Normal", "Maya Kowalska",
      "2026-08-18T08:16:16.000Z", "2026-08-21T12:58:19.000Z", "2026-08-31", "ORB-10",
      "## Context\n\nThe `InvoiceRepository` & its **six** methods.\n\n- one\n- two [link](https://example.com)",
      "billing", "q3",
    ]);
    // Kept apart from the columns, known by Jira's own comment id
    expect(table.comments).toEqual([
      [
        { id: "jira-501", createdAt: "2026-08-19T07:00:00.000Z", author: "Jan Nowak", body: "Looks good; ship it" },
        { id: "jira-502", createdAt: "2026-08-20T11:30:00.000Z", author: "712020:zzz", body: "Second" },
      ],
      [],
    ]);
    expect(table.rows[1].slice(0, 10)).toEqual(["ORB-13", "Sign in", "Bug", "To Do", "Highest", "", "2026-08-22T08:00:00.000Z", "", "", ""]);
  });

  it("goes through the CSV path into a bundle the engine accepts, its comments named and its text left as Markdown", () => {
    const table = jiraXmlToTable(XML, new DOMParser())!;
    const fields = [{ name: "Labels", fieldType: "multiselect" }];
    const bundle = csvToBundle(table, guessTargets(table.headers, fields), "Jira", fields, "u1");
    expect(parseBundle(bundle).ok).toBe(true);
    expect(bundle.tasks[0]).toMatchObject({
      id: "ORB-12",
      parent: "ORB-10",
      dueDate: "2026-08-31",
      fields: { Labels: ["billing", "q3"] },
      comments: [
        { id: "jira-501", author: "Jan Nowak", body: "Looks good; ship it", createdAt: "2026-08-19T07:00:00.000Z" },
        { id: "jira-502", author: "712020:zzz", body: "Second" },
      ],
    });
    expect(bundle.tasks[0].description).toContain("**six**");
  });

  it("refuses a file that is not XML", () => {
    expect(jiraXmlToTable("<rss><item><key>x</item>", new DOMParser())).toBeNull();
  });
});

describe("htmlToMarkdown", () => {
  it("keeps code and tables readable", () => {
    expect(htmlToMarkdown("<pre>a  b\n c</pre><table><tr><th>A</th><th>B</th></tr><tr><td>1</td><td>2</td></tr></table>", new DOMParser())).toBe(
      "```\na  b\n c\n```\n\n| A | B |\n| 1 | 2 |"
    );
  });
});

describe("a re-export", () => {
  it("keeps every comment's identity when its author is named differently the next time", () => {
    const again = XML.replace('<reporter accountid="712020:bbb">Jan Nowak</reporter>', '<reporter accountid="712020:ccc">Someone Else</reporter>').replace(
      '<reporter accountid="712020:bbb">Jan Nowak</reporter>',
      '<reporter accountid="712020:ccc">Someone Else</reporter>'
    );
    const ids = (xml: string) => jiraXmlToTable(xml, new DOMParser())!.comments![0].map((c) => [c.id, c.author]);
    expect(ids(XML)).toEqual([["jira-501", "Jan Nowak"], ["jira-502", "712020:zzz"]]);
    expect(ids(again)).toEqual([["jira-501", "712020:bbb"], ["jira-502", "712020:zzz"]]);
  });
});

describe("Jira Server and Data Center", () => {
  it("reads their unassigned marker, written under username", () => {
    const dc = XML.replace('<assignee accountid="-1">Unassigned</assignee>', '<assignee username="-1">Unassigned</assignee>');
    expect(jiraXmlToTable(dc, new DOMParser())!.rows[1][5]).toBe("");
  });
});
